"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["75077"],{626308(n){n.exports=JSON.parse('{"id":10690,"title":"\u8BBE\u8BA1html\u539F\u578B\u63D0\u793A\u8BCD","description":"# \u4EFB\u52A1\u76EE\u6807\\n\\n\u8BF7\u6839\u636E\u6211\u63D0\u4F9B\u7684\u300C\u8BBE\u8BA1\u8BF4\u660E\u6587\u6863\u300D\uFF0C\u5236\u4F5C\u4E00\u4E2A **\u4EA4\u4E92\u539F\u578B HTML \u6587\u4EF6**\u3002\\n\\n## \u91CD\u8981\u8BF4\u660E\uFF08\u5FC5\u987B\u9075\u5B88\uFF09\\n\\n1. **\u8F93\u51FA\u4E00\u4E2A\u5B8C\u6574\u7684 HTML \u6587\u4EF6**\uFF0C\u53EF\u76F4\u63A5\u5728\u6D4F\u89C8\u5668\u6253\u5F00\u8FD0\u884C\\n2. **\u53EA\u505A\u754C\u9762\uFF0C\u4E0D\u505A\u5177\u4F53\u903B\u8F91**\uFF1A\\n   - \u4E0D\u9700\u8981\u5B9E\u73B0\u771F\u5B9E\u7684\u540E\u7AEF\u63A5\u53E3\u8C03\u7528\\n   - \u4E0D\u9700\u8981\u5B9E\u73B0\u771F\u5B9E\u7684\u6570\u636E\u5E93\u64CD\u4F5C\\n   - \u4E0D\u9700\u8981\u5B9E\u73B0\u771F\u5B9E\u7684\u4E1A\u52A1\u903B\u8F91\uFF08\u5982\u767B\u5F55\u9A8C\u8BC1\u3001\u8868\u5355\u63D0\u4EA4\u3001\u6570\u636E\u5904\u7406\u7B49\uFF09\\n   - \u70B9\u51FB\u6309\u94AE\u3001\u63D0\u4EA4\u8868\u5355\u7B49\u64CD\u4F5C**\u53EA\u9700\u8981UI\u5C42\u9762\u7684\u53CD\u9988**\uFF0C\u4E0D\u9700\u8981\u771F\u6B63\u6267\u884C\u529F\u80FD\\n\\n3. **\u4F7F\u7528\u5047\u6570\u636E**\uFF1A\\n   - \u7F16\u9020\u5408\u7406\u7684\u6F14\u793A\u6570\u636E\u6765\u586B\u5145\u754C\u9762\\n   - \u6570\u636E\u8981\u771F\u5B9E\u611F\u5F3A\uFF0C\u80FD\u591F\u5C55\u793A\u754C\u9762\u7684\u5B8C\u6574\u6548\u679C\\n\\n---\\n\\n## \u4EA4\u4E92\u539F\u578B\u9700\u8981\u5B9E\u73B0\u7684\u6548\u679C\\n\\n\u8FD9\u662F\u539F\u578B\u754C\u9762\uFF0C\u6240\u4EE5\u9700\u8981\u8BA9\u754C\u9762\\"\u770B\u8D77\u6765\u80FD\u7528\u3001\u52A8\u8D77\u6765\\"\uFF1A\\n\\n### \u5FC5\u987B\u5B9E\u73B0\u7684UI\u4EA4\u4E92\\n- **hover\u6548\u679C**\uFF1A\u6309\u94AE\u3001\u5361\u7247\u3001\u94FE\u63A5\u7684\u60AC\u505C\u72B6\u6001\u53D8\u5316\\n- **\u70B9\u51FB\u53CD\u9988**\uFF1A\u6309\u94AE\u70B9\u51FB\u65F6\u6709\u89C6\u89C9\u53CD\u9988\uFF08\u989C\u8272\u53D8\u5316\u3001\u7F29\u653E\u7B49\uFF09\\n- **\u8FC7\u6E21\u52A8\u753B**\uFF1A\u72B6\u6001\u5207\u6362\u65F6\u6709\u5E73\u6ED1\u7684CSS\u8FC7\u6E21\\n- **\u5165\u573A\u52A8\u753B**\uFF1A\u9875\u9762\u52A0\u8F7D\u65F6\u5143\u7D20\u6709\u6E10\u663E\u52A8\u753B\\n\\n### \u53EF\u9009\u5B9E\u73B0\u7684\u6A21\u62DF\u4EA4\u4E92\uFF08\u7528JS\u6A21\u62DF\uFF09\\n- Tab\u6807\u7B7E\u5207\u6362\\n- \u4E0B\u62C9\u83DC\u5355\u5C55\u5F00/\u6536\u8D77\\n- \u6A21\u6001\u6846\u5F39\u51FA/\u5173\u95ED\\n- \u4FA7\u8FB9\u680F\u6298\u53E0/\u5C55\u5F00\\n- \u8868\u5355\u5B57\u6BB5\u805A\u7126\u6837\u5F0F\\n\\n**\u6CE8\u610F**\uFF1A\u4EE5\u4E0A\u4EA4\u4E92\u90FD\u662FUI\u5C55\u793A\u5C42\u9762\uFF0C\u4E0D\u9700\u8981\u771F\u6B63\u5B9E\u73B0\u529F\u80FD\u903B\u8F91\u3002\\n\\n---\\n\\n## \u8BBE\u8BA1\u8981\u6C42\\n\\n- \u914D\u8272\u8981\u6709\u8BBE\u8BA1\u611F\uFF0C\u7981\u6B62\u9ED8\u8BA4\u6A21\u677F\u98CE\u683C\\n- \u5E03\u5C40\u6E05\u6670\uFF0C\u89C6\u89C9\u5C42\u6B21\u5206\u660E\\n- \u54CD\u5E94\u5F0F\u8BBE\u8BA1\uFF0C\u9002\u914D\u79FB\u52A8\u7AEF\u548C\u684C\u9762\u7AEF\\n- \u4E0D\u4F7F\u7528 emoji\\n\\n---\\n\\n# \u8BBE\u8BA1\u8BF4\u660E\u6587\u6863\\n\\n[\u5728\u6B64\u5904\u7C98\u8D34\u4F60\u7684\u8BBE\u8BA1\u6587\u6863\u5185\u5BB9]\\n","owner":"dongjiang","upvotes":3,"downvotes":0,"upvoteDifference":3,"updatedAt":"2026-04-16T07:32:49.519Z"}')}}]);